S = [
("m5.name", "Crashes and stability", "الانهيارات والاستقرار"),
("m5.check.events", "Crash-related events in the System and Application logs", "الأحداث المتعلقة بالانهيار في سجلَّي النظام والتطبيقات"),
("m5.check.events.detail", "{0} events read from the last {1} days; {2} unexpected stops.", "قُرئ {0} حدثاً من آخر {1} يوماً؛ {2} توقفاً غير متوقع."),
("m5.check.suppressed", "Known harmless events", "أحداث معروفة بأنها غير ضارة"),
("m5.check.suppressed.detail", "{0} Kernel-PnP 219 events for WudfRd at startup were not reported: they are a harmless timing message.", "لم يُبلّغ عن {0} حدثاً من Kernel-PnP 219 الخاص بـWudfRd عند بدء التشغيل: إنها رسالة توقيت غير ضارة."),
("m5.check.stability", "Reliability Monitor stability index", "مؤشر الاستقرار في مراقب الموثوقية"),
("m5.check.stability.detail", "{0} of 10 (as of {1}).", "{0} من 10 (بتاريخ {1})."),
("m5.check.stability.none", "Reliability data is not being collected on this PC.", "لا تُجمع بيانات الموثوقية على هذا الجهاز."),
("m5.check.dumpAnalysis", "Crash dump analysis with the Windows debugger", "تحليل ملفات التفريغ بمصحح أخطاء ويندوز"),
("m5.check.dumpConfig", "Crash dump setting", "إعداد تفريغ الذاكرة عند الانهيار"),
("m5.dumpMode.none", "Off: blue screens leave no dump file.", "متوقف: الشاشات الزرقاء لا تترك ملف تفريغ."),
("m5.dumpMode.complete", "Complete memory dump.", "تفريغ كامل للذاكرة."),
("m5.dumpMode.kernel", "Kernel memory dump.", "تفريغ ذاكرة النواة."),
("m5.dumpMode.small", "Small memory dump (minidump).", "تفريغ صغير للذاكرة (minidump)."),
("m5.dumpMode.automatic", "Automatic memory dump (Windows default).", "تفريغ تلقائي للذاكرة (الإعداد الافتراضي في ويندوز)."),
("m5.dumpMode.unknown", "Unrecognised value.", "قيمة غير معروفة."),
("m5.dumpsDisabled.title", "Crash dumps are turned off", "تفريغ الذاكرة عند الانهيار متوقف"),
("m5.dumpsDisabled.why", "Without a dump file, the cause of the next blue screen cannot be identified.", "بدون ملف تفريغ لا يمكن تحديد سبب الشاشة الزرقاء القادمة."),
("m5.dumpsDisabled.action", "Turn on automatic crash dumps (Windows' default). PC Doctor can do it for you, with undo.", "فعّل تفريغ الذاكرة التلقائي (الإعداد الافتراضي في ويندوز). يستطيع طبيب الحاسوب فعل ذلك مع إمكانية التراجع."),
("m5.dumpsDisabled.undo", "The old value is kept in the change journal and can be put back from the Changes tab.", "تُحفظ القيمة القديمة في سجل التغييرات ويمكن إعادتها من تبويب التغييرات."),
("m5.noPagefile.title", "No page file is configured", "لا يوجد ملف ترحيل مُعدّ"),
("m5.noPagefile.why", "Windows writes crash dumps through the page file; without one, a blue screen may leave no dump.", "يكتب ويندوز ملفات التفريغ عبر ملف الترحيل؛ وبدونه قد لا تترك الشاشة الزرقاء ملف تفريغ."),
("m5.noPagefile.action", "Set the page file back to \"Automatically manage\" in System Properties > Advanced > Performance > Virtual memory.", "أعد ملف الترحيل إلى \"إدارة تلقائية\" من خصائص النظام > خيارات متقدمة > الأداء > الذاكرة الظاهرية."),
("m5.dumpFailed.title", "Windows could not save a crash dump ({0} times)", "تعذّر على ويندوز حفظ ملف التفريغ ({0} مرات)"),
("m5.dumpFailed.why", "The crash happened, but the file that would explain it was not written (volmgr event 161).", "حدث الانهيار، لكن الملف الذي يشرحه لم يُكتب (الحدث 161 من volmgr)."),
("m5.dumpFailed.action", "Check that the page file is system-managed and the system drive has free space.", "تأكد أن ملف الترحيل يُدار من النظام وأن قرص النظام فيه مساحة فارغة."),
("m5.check.dumps", "Crash dump files", "ملفات تفريغ الانهيار"),
("m5.check.dumps.detail", "{0} dump files found; newest {1}.", "عُثر على {0} ملف تفريغ؛ أحدثها {1}."),
("m5.check.dumps.none", "No crash dump files on this PC.", "لا توجد ملفات تفريغ انهيار على هذا الجهاز."),
("m5.bsod.title", "{0} of {1} blue screens in {2} days had stop code {3} ({4})", "{0} من {1} شاشات زرقاء خلال {2} يوماً كان رمز الإيقاف فيها {3} ({4})"),
("m5.bsod.why.unknown", "PC Doctor's knowledge base has no explanation for this stop code yet.", "لا تحتوي قاعدة معارف طبيب الحاسوب على شرح لرمز الإيقاف هذا بعد."),
("m5.bsod.action.unknown", "Look up the stop code in Microsoft's bug check reference.", "ابحث عن رمز الإيقاف في مرجع رموز الأخطاء من مايكروسوفت."),
("m5.forcedOff.title", "The PC was forced off while unresponsive ({0} times)", "أُطفئ الجهاز قسراً وهو لا يستجيب ({0} مرات)"),
("m5.forcedOff.why", "Windows recorded that the power button was held down. That usually means the PC froze.", "سجّل ويندوز أن زر التشغيل ضُغط مطوّلاً. يعني ذلك عادة أن الجهاز تجمّد."),
("m5.forcedOff.action", "Note what was running when it froze. Check graphics and storage drivers and temperatures.", "لاحظ ما كان يعمل عند التجمد. تحقق من تعريفات الرسوميات والتخزين ومن درجات الحرارة."),
("m5.forcedOff.action.related", "{0} related events (graphics or storage resets, hardware errors) happened just before. See the evidence.", "وقع {0} حدثاً مرتبطاً (إعادة تعيين الرسوميات أو التخزين، أخطاء عتاد) قبل ذلك مباشرة. راجع الأدلة."),
("m5.powerLoss.title", "The PC stopped without shutting down ({0} times)", "توقف الجهاز دون إيقاف تشغيل سليم ({0} مرات)"),
("m5.powerLoss.why", "There was no blue screen and no power-button press: power was lost or the PC hung hard.", "لم تظهر شاشة زرقاء ولم يُضغط زر التشغيل: انقطعت الطاقة أو تجمّد الجهاز تماماً."),
("m5.powerLoss.action", "Check hardware errors below, the power supply and cabling, temperatures, and remove overclocks.", "راجع أخطاء العتاد أدناه، ومزوّد الطاقة والكابلات، ودرجات الحرارة، وألغِ رفع التردد."),
("m5.powerLoss.action.related", "{0} related events (graphics or storage resets, hardware errors) happened just before. See the evidence.", "وقع {0} حدثاً مرتبطاً (إعادة تعيين الرسوميات أو التخزين، أخطاء عتاد) قبل ذلك مباشرة. راجع الأدلة."),
("m5.wheaFatal.title", "Fatal hardware errors reported ({0})", "أُبلغ عن أخطاء عتاد قاتلة ({0})"),
("m5.wheaFatal.why", "The processor or memory reported an error it could not correct (WHEA-Logger 18).", "أبلغ المعالج أو الذاكرة عن خطأ لم يتمكن من تصحيحه (WHEA-Logger 18)."),
("m5.wheaPcie.title", "{0} corrected PCI Express errors from device {1}", "{0} خطأ PCI Express مُصحّح من الجهاز {1}"),
("m5.wheaPcie.why", "Corrected errors are fixed by the hardware, but many of them can point to a loose card, a riser cable or link power saving problems.", "تُصحَّح هذه الأخطاء بواسطة العتاد، لكن كثرتها قد تشير إلى بطاقة غير مثبتة جيداً أو كابل توصيل أو مشكلات توفير طاقة الرابط."),
("m5.wheaPcie.action", "Reseat the device, update chipset drivers and BIOS. The vendor and device IDs identify the device.", "أعد تركيب الجهاز، وحدّث تعريفات الشرائح وBIOS. معرّفا المصنّع والجهاز يحددان الجهاز."),
("m5.wheaCorrected.title", "Corrected processor or memory errors ({0})", "أخطاء مُصحّحة في المعالج أو الذاكرة ({0})"),
("m5.wheaCorrected.why", "The hardware fixed these itself, but they often precede uncorrectable errors on unstable overclocks or failing memory.", "أصلحها العتاد بنفسه، لكنها غالباً تسبق أخطاء غير قابلة للتصحيح عند رفع تردد غير مستقر أو ذاكرة تتعطل."),
("m5.tdr.title", "The display driver stopped responding and recovered {0} times", "توقف تعريف العرض عن الاستجابة ثم تعافى {0} مرات"),
("m5.tdr.why", "Windows reset the graphics driver (Display event 4101). Repeated resets can end in a freeze or blue screen.", "أعاد ويندوز تعيين تعريف الرسوميات (الحدث 4101). تكرار ذلك قد ينتهي بتجمّد أو شاشة زرقاء."),
("m5.tdr.action", "Install the current driver from the GPU maker, remove GPU overclocks and check GPU temperatures. Do not edit the TDR registry keys.", "ثبّت أحدث تعريف من الشركة المصنّعة لبطاقة الرسوميات، وألغِ رفع ترددها، وراقب حرارتها. لا تعدّل مفاتيح TDR في السجل."),
("m5.firmwareLimit.title", "Firmware limited the processor speed ({0} times)", "حدّ البرنامج الثابت من سرعة المعالج ({0} مرات)"),
("m5.firmwareLimit.why", "This is not a failure. It means the CPU was slowed, often because of heat or power limits (Kernel-Processor-Power 37).", "ليس هذا عطلاً. يعني أن المعالج أُبطئ، غالباً بسبب الحرارة أو حدود الطاقة (Kernel-Processor-Power 37)."),
("m5.firmwareLimit.action", "If the PC feels slow, check cooling and the power plan. On laptops this is common on battery.", "إذا شعرت ببطء الجهاز فتحقق من التبريد وخطة الطاقة. في الحواسيب المحمولة هذا شائع عند العمل على البطارية."),
("m5.storage.disk7.title", "The disk reported bad blocks ({0} events)", "أبلغ القرص عن كتل تالفة ({0} حدثاً)"),
("m5.storage.disk7.why", "Part of the disk could not be read reliably. Data in those blocks may be lost.", "تعذّرت قراءة جزء من القرص بشكل موثوق. قد تُفقد البيانات في تلك الكتل."),
("m5.storage.disk11.title", "The disk controller reported errors ({0} events)", "أبلغ متحكم القرص عن أخطاء ({0} حدثاً)"),
("m5.storage.disk11.why", "Commands to the disk failed. Cables, ports, the controller driver or the disk itself can cause this.", "فشلت أوامر إلى القرص. قد يكون السبب الكابلات أو المنافذ أو تعريف المتحكم أو القرص نفسه."),
("m5.storage.disk51.title", "Errors while paging to disk ({0} events)", "أخطاء أثناء الترحيل إلى القرص ({0} حدثاً)"),
("m5.storage.disk51.why", "Windows had trouble writing memory pages to disk, which can cause freezes and crashes.", "واجه ويندوز صعوبة في كتابة صفحات الذاكرة إلى القرص، مما قد يسبب تجمّداً وانهيارات."),
("m5.storage.ntfs55.title", "File system corruption detected ({0} events)", "اكتُشف تلف في نظام الملفات ({0} حدثاً)"),
("m5.storage.ntfs55.why", "NTFS found damaged file system structures. Files on that volume may be affected.", "وجد NTFS بنى تالفة في نظام الملفات. قد تتأثر الملفات على ذلك المجلد."),
("m5.storage.ntfs98.title", "A volume needs a file system check ({0} events)", "يحتاج مجلد إلى فحص نظام الملفات ({0} حدثاً)"),
("m5.storage.ntfs98.why", "NTFS marked a volume as needing repair.", "وضع NTFS علامة على مجلد بأنه يحتاج إلى إصلاح."),
("m5.storage.ntfs50.title", "Delayed writes failed ({0} events)", "فشلت عمليات كتابة مؤجلة ({0} حدثاً)"),
("m5.storage.ntfs50.why", "Data Windows had cached could not be written to disk, so some changes may be lost.", "تعذّرت كتابة بيانات خزّنها ويندوز مؤقتاً إلى القرص، لذا قد تُفقد بعض التغييرات."),
("m5.storage.ntfs140.title", "Failed file system flushes ({0} events)", "فشل تفريغ نظام الملفات ({0} حدثاً)"),
("m5.storage.ntfs140.why", "Often logged when a USB drive is removed without ejecting. Repeated on an internal disk, it can point to a storage problem.", "يُسجَّل غالباً عند نزع قرص USB دون إخراجه. تكراره على قرص داخلي قد يشير إلى مشكلة في التخزين."),
("m5.storage.storport129.title", "The storage driver reset the disk ({0} events)", "أعاد تعريف التخزين تعيين القرص ({0} حدثاً)"),
("m5.storage.storport129.why", "The disk stopped answering and was reset. This often comes before freezes.", "توقف القرص عن الاستجابة وأُعيد تعيينه. يسبق ذلك التجمّد غالباً."),
("m5.storage.storport153.title", "Disk operations were retried ({0} events)", "أُعيدت محاولة عمليات القرص ({0} حدثاً)"),
("m5.storage.storport153.why", "Reads or writes timed out and were retried. Firmware, drivers, cables or a failing disk can cause this.", "انتهت مهلة القراءة أو الكتابة وأُعيدت المحاولة. قد يسببه البرنامج الثابت أو التعريفات أو الكابلات أو قرص يتعطل."),
("m5.storage.disk157.title", "A disk was removed unexpectedly ({0} events)", "أُزيل قرص بشكل غير متوقع ({0} حدثاً)"),
("m5.storage.disk157.why", "Normal for USB drives pulled out without ejecting. For an internal disk it can mean a loose connection.", "طبيعي لأقراص USB المنزوعة دون إخراج. أما للقرص الداخلي فقد يعني توصيلاً غير محكم."),
("m5.storage.action", "Check the disk health section, update storage drivers and SSD firmware, and check cables.", "راجع قسم صحة الأقراص، وحدّث تعريفات التخزين والبرنامج الثابت لقرص SSD، وتحقق من الكابلات."),
("m5.storage.action.backup", "Back up your files now, then check the disk health section and run a read-only disk check (chkdsk /scan).", "انسخ ملفاتك احتياطياً الآن، ثم راجع قسم صحة الأقراص وشغّل فحص القرص للقراءة فقط (chkdsk /scan)."),
("m5.serviceCrash.title", "The service \"{0}\" stopped unexpectedly {1} times", "توقفت الخدمة \"{0}\" بشكل غير متوقع {1} مرات"),
("m5.serviceCrash.why", "A background service crashed. Windows may have restarted it, but whatever it provides was interrupted.", "انهارت خدمة تعمل في الخلفية. ربما أعاد ويندوز تشغيلها، لكن ما تقدمه قد انقطع."),
("m5.serviceCrash.action", "Update or reinstall the app the service belongs to.", "حدّث التطبيق الذي تتبع له الخدمة أو أعد تثبيته."),
("m5.serviceStart.title", "{0} services failed to start or timed out", "{0} خدمات فشلت في البدء أو انتهت مهلتها"),
("m5.serviceStart.why", "This is common on healthy PCs (for example, a service for a device that is not present). It matters only if something you use does not work.", "هذا شائع في الأجهزة السليمة (مثل خدمة لجهاز غير موجود). لا يهم إلا إذا كان شيء تستخدمه لا يعمل."),
("m5.serviceStart.action", "If a feature you use is broken, update or reinstall the app that owns the service named in the evidence.", "إذا كانت ميزة تستخدمها معطلة، فحدّث أو أعد تثبيت التطبيق المالك للخدمة المذكورة في الأدلة."),
("m5.app.title", "{0} crashed {1} times and stopped responding {2} times", "انهار {0} {1} مرات وتوقف عن الاستجابة {2} مرات"),
("m5.app.why", "Repeated crashes of one app usually come from that app or a plug-in it loads, not from Windows.", "الانهيارات المتكررة لتطبيق واحد تأتي عادة من التطبيق نفسه أو من إضافة يحمّلها، لا من ويندوز."),
("m5.app.action", "Update or reinstall the app. If the faulting module in the evidence belongs to another product, update that product.", "حدّث التطبيق أو أعد تثبيته. إذا كانت الوحدة المسببة في الأدلة تتبع منتجاً آخر فحدّث ذلك المنتج."),
]
